import { BaseGoogleSheet } from "../BaseGoogleSheet";
import type { GoogleSheetRow, IGoogleRowsSheet } from "../../types";

export class RecordsSheet extends BaseGoogleSheet implements IGoogleRowsSheet {
  async readRows(range = "A:Z"): Promise<GoogleSheetRow[]> { return this.read(range); }
